import {dualRows,dualStages} from './dual-model.mjs';
import {rung,contact} from './ladder.mjs';
function outputSVG(states,s,tag,value){const ys=states.map((_,i)=>34+i*60),last=ys.at(-1);return `<svg viewBox="0 0 420 ${last+30}" role="img" aria-label="${tag} = ${Number(value)}"><path class="rail on" d="M15 10V${last+12}"/><path class="rail" d="M405 10V${last+12}"/><path class="wire on" d="M15 34H55V${last}"/>${states.map((stage,i)=>`<path class="wire on" d="M55 ${ys[i]}H114"/>${contact({tag:dualStages[stage],pass:s.state===stage},120,ys[i])}<path class="wire ${s.state===stage?'on':''}" d="M126 ${ys[i]}H245"/>`).join('')}${ys.slice(1).map((y,i)=>`<path class="wire ${states.slice(i+1).includes(s.state)?'on':''}" d="M245 ${ys[i]}V${y}"/>`).join('')}<path class="wire ${value?'on':''}" d="M245 34H316M370 34H405"/><g class="coil ${value?'on':''}"><text x="345" y="13">${tag}</text><path d="M333 19Q314 34 333 49M357 19Q376 34 357 49"/><text x="345" y="38">${Number(value)}</text></g></svg>`;}
export function createDualLadder({host,inspector,onPlay,onScan,onChange}){const panel=document.createElement('section');panel.className='ladder-panel';panel.setAttribute('aria-label','Ladder de dos cilindros');panel.innerHTML=`<span class="eyebrow">DOS ACTUADORES / UN SECUENCIADOR</span><h2>A+ → B+ → B− → A−</h2><p class="ladder-legend"><b>Verde = verdadero</b> · línea verde = continuidad lógica. + extiende; − retrae.</p><div class="ladder-actions"><button id="ladderPlay">Reproducir</button><button id="ladderScan">+1 scan</button><label><input id="breakTransition" type="checkbox"> Pausar al cambiar etapa</label></div><div id="dualSteps"></div><div id="ladderClock"></div><div id="ladderRungs"></div><details class="ladder-help"><summary>06–09 · Supervisión de sensores</summary><div id="faultRungs"></div></details><div id="ladderOutput"></div><p id="ladderRead" role="status"></p><details class="ladder-help"><summary>Cómo coordina los dos cilindros</summary><p>01–09 evalúan una imagen de entradas y etapa; solo se confirma una transición por scan. Los contactos en serie son AND; las ramas paralelas son OR. MOV escribe la siguiente etapa. Las redes 10 y 11 escriben salidas con esa etapa resultante.</p><p>A debe mantenerse extendido durante A+, B+ y B−: esas tres ramas activan Q0.0. Q0.1 solo está activa durante B+. Al quitar una salida, su válvula 5/2 vuelve por muelle y ese cilindro retorna.</p><p>—|/|— comprueba sensor falso. Si falta confirmación por más de carrera + 1 s, ambas salidas caen y ambos cilindros retornan; en fallo ya no se respeta el orden normal. El rearme exige a0 y b0. Ladder didáctico, no programa de seguridad ni archivo para un PLC comercial.</p></details>`;host.append(panel);const details=document.createElement('details');details.className='plc-inspection';details.innerHTML='<summary>Explorar cilindros, sensores y válvulas</summary>';host.after(details);details.append(inspector);panel.querySelector('#ladderPlay').onclick=onPlay;panel.querySelector('#ladderScan').onclick=onScan;let selected='01',cache='';panel.addEventListener('click',e=>{const b=e.target.closest('[data-rung]');if(b){selected=b.dataset.rung;cache='';onChange();}});
 return {panel,update(s,ta,tb,playing,disabled){panel.querySelector('#ladderPlay').textContent=playing?'Pausar':'Reproducir';panel.querySelector('#ladderPlay').disabled=panel.querySelector('#ladderScan').disabled=disabled;const rows=s.scan?.rows||dualRows(s,ta,tb),key=JSON.stringify([rows,s.state,Math.floor(s.time*10),selected]);if(key===cache)return;cache=key;
 panel.querySelector('#dualSteps').innerHTML=['AP','BP','BM','AM'].map(st=>`<span class="${s.state===st?'active':''}">${dualStages[st]}</span>`).join('');
 panel.querySelector('#ladderClock').textContent=`${s.scan?'Último scan':'Antes del primer scan'} · ${s.time.toFixed(2)} s · ${dualStages[s.scan?.state||s.state]} → ${dualStages[s.state]} · t=${(s.scan?.age||0).toFixed(2)} s`;
 for(const r of rows){const parent=panel.querySelector(+r.id<=5?'#ladderRungs':'#faultRungs');let b=parent.querySelector(`[data-rung="${r.id}"]`);if(!b){b=document.createElement('button');b.dataset.rung=r.id;parent.append(b)}b.className=`ladder-rung ${r.active&&s.scan?'energized':''}`;b.setAttribute('aria-pressed',String(selected===r.id));b.setAttribute('aria-label',`${r.id}. ${r.note} ${r.contacts.map(c=>c.tag+': '+c.pass).join(', ')}`);const markup=`<span>${r.id}</span>${rung(r,dualStages)}`;if(b.innerHTML!==markup)b.innerHTML=markup;}
 panel.querySelector('#ladderOutput').innerHTML=`<span class="eyebrow">10 · MANTENER A DURANTE EL RECORRIDO DE B</span>${outputSVG(['AP','BP','BM'],s,'Q0.0 / YA',s.q)}<span class="eyebrow">11 · B SOLO AVANZA EN LA ETAPA B+</span>${outputSVG(['BP'],s,'Q0.1 / YB',s.qB)}<strong>YA=${Number(s.q)} · YB=${Number(s.qB)} · ${s.fault?'Fallo: retorno de ambos':dualStages[s.state]}</strong>`;
 const r=rows.find(r=>r.id===selected),text=`${r.id} · ${r.note} ${s.scan?(r.active?'Se ejecutó en este scan.':'No se ejecutó en este scan.'):'Aún no ejecutado.'}`,read=panel.querySelector('#ladderRead');if(read.textContent!==text)read.textContent=text;
 }};
}
